import { test, expect } from '@playwright/test';

test.describe('Login with Email or Username', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://practicetestautomation.com/practice-test-login/');
  });

  test('should successfully log in with username', async ({ page }) => {
    // Fill in the username field
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('student');

    // Fill in the password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Password123');

    // Click the submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify successful login
    const successMessage = page.getByText(/logged in successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should successfully log in with email format', async ({ page }) => {
    // Fill in the username field with email format
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('student@example.com');

    // Fill in the password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Password123');

    // Click the submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify successful login
    const successMessage = page.getByText(/logged in successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should show error message with invalid credentials', async ({ page }) => {
    // Fill in the username field
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('invaliduser');

    // Fill in the password field with wrong password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('WrongPassword');

    // Click the submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/your username is invalid/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should clear fields and allow retry after failed login', async ({ page }) => {
    // First attempt with invalid credentials
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('invaliduser');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('WrongPassword');

    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error message
    const errorMessage = page.getByText(/your username is invalid/i);
    await expect(errorMessage).toBeVisible();

    // Clear fields and retry with valid credentials
    await usernameInput.clear();
    await usernameInput.fill('student');

    await passwordInput.clear();
    await passwordInput.fill('Password123');

    await submitButton.click();

    // Verify successful login after retry
    const successMessage = page.getByText(/logged in successfully/i);
    await expect(successMessage).toBeVisible();
  });
});
